117	fn handle_declaration_name_comment(
118	    comment: DecoratedComment<CssLanguage>,
119	) -> CommentPlacement<CssLanguage> {
120	    let Some(preceding_node) = comment.preceding_node() else {
121	        return CommentPlacement::Default(comment);
122	    };
123	
124	    if !AnyCssDeclarationName::can_cast(preceding_node.kind()) {
125	        return CommentPlacement::Default(comment);
126	    }
127	
128	    // The declaration name can also appear as a value component (e.g. a dashed
129	    // identifier used as a value), in which case the parent is a component value
130	    // list rather than a property. Those comments are left to the default handling.
131	    let Some(property) = preceding_node.parent().and_then(CssGenericProperty::cast) else {
132	        return CommentPlacement::Default(comment);
133	    };
134	
135	    let Ok(colon_token) = property.colon_token() else {
136	        return CommentPlacement::Default(comment);
137	    };
138	
139	    if comment.piece().text_range().start() < colon_token.text_range().start() {
140	        // The comment sits between the property name and the colon, e.g.
141	        // `color /* comment */: value`. Keep it attached to the name so that it
142	        // stays between the name and the colon instead of being moved before the
143	        // property name.
144	        CommentPlacement::trailing(preceding_node.clone(), comment)
145	    } else {
146	        // The comment sits between the colon and the value, e.g.
147	        // `color: /* comment */ value`. Attach it to the property as a dangling
148	        // comment so the generic property formatter can render it right after the
149	        // colon and push the value onto the next line.
150	        CommentPlacement::dangling(property.into_syntax(), comment)
151	    }
152	}
